Tool response:
Tool: update_cancellation_policy
Description: Modify the cancellation policy for a specific rate plan to require a specified number of notice days for a full refund.
This endpoint updates the notice_days and refund_percentage fields in the cancellation_policies table.
Parameters:
    {
      "type": "object",
      "properties": {
        "rate_plan_id": {
          "type": "integer",
          "description": "Internal ID of the rate plan to update",
          "title": "Rate Plan Id"
        },
        "notice_days": {
          "type": "integer",
          "title": "Notice Days"
        },
        "refund_percentage": {
          "type": "number",
          "title": "Refund Percentage"
        }
      },
      "required": [
        "rate_plan_id",
        "notice_days",
        "refund_percentage"
      ]
    }

Tool response:
Tool: get_cancellation_policy
Description: Fetch the current cancellation policy details for a specific rate plan, including notice days and refund percentage.
Parameters:
    {
      "type": "object",
      "properties": {
        "rate_plan_id": {
          "type": "integer",
          "description": "Internal ID of the rate plan",
          "title": "Rate Plan Id"
        }
      },
      "required": [
        "rate_plan_id"
      ]
    }
